import {
  existsSync,
  mkdirSync,
  readFileSync,
  writeFileSync,
  watch,
} from "node:fs";
import { createRequire } from "node:module";
import { join, resolve } from "node:path";
import { pathToFileURL } from "node:url";
import type { BuildContext, BuildResult } from "esbuild";

export const AUTH_PAGE_FILE = "tapedb.auth.tsx";
const GENERATED = "auth-page.gen.ts";
function generated(root: string, javascript?: string, css?: string) {
  const file = join(root, "tapedb", GENERATED);
  const source =
    '// Generated by tapedb from tapedb.auth.tsx. Do not edit.\nimport type { TapeDBAuthPage } from "@tapedb/tapedb/worker";\nexport const authPage: TapeDBAuthPage | undefined = ' +
    (javascript
      ? JSON.stringify({ javascript, ...(css ? { css } : {}) })
      : "undefined") +
    ";\n";
  mkdirSync(join(root, "tapedb"), { recursive: true });
  if (!existsSync(file) || readFileSync(file, "utf8") !== source)
    writeFileSync(file, source);
}
/** Discover the conventional React page; keep its browser code out of Worker execution. */
export async function prepareAuthPage(
  root: string,
  live = false,
): Promise<{ close(): Promise<void> }> {
  root = resolve(root);
  let context: BuildContext | undefined,
    closed = false;
  const require = createRequire(join(root, "package.json"));
  async function start() {
    if (closed) return;
    if (!existsSync(join(root, AUTH_PAGE_FILE))) {
      await context?.dispose();
      context = undefined;
      generated(root);
      return;
    }
    if (context) return;
    let modulePath: string;
    try {
      modulePath = require.resolve("esbuild");
    } catch {
      throw new Error(
        "Custom auth pages need esbuild, react and react-dom in the project. Run tapedb init to install them.",
      );
    }
    const esbuild = (await import(
      pathToFileURL(modulePath).href
    )) as typeof import("esbuild");
    const onResult = (result: BuildResult) => {
      if (result.errors.length) return;
      const javascript = result.outputFiles?.find((file) =>
        file.path.endsWith(".js"),
      )?.text;
      if (!javascript)
        throw new Error("The auth page build produced no browser entry.");
      const css = result.outputFiles?.find((file) =>
        file.path.endsWith(".css"),
      )?.text;
      generated(root, javascript, css);
    };
    const input =
      'import {createElement} from "react";import {createRoot} from "react-dom/client";import AuthPage from "./' +
      AUTH_PAGE_FILE +
      '";const requested=new URLSearchParams(location.search).get("returnTo")||"/_tapedb/studio";let redirectTo="/_tapedb/studio";try{const target=new URL(requested,location.origin);if(target.origin===location.origin&&target.pathname!=="/auth")redirectTo=target.pathname+target.search+target.hash;}catch{}createRoot(document.getElementById("root")).render(createElement(AuthPage,{redirectTo}));';
    context = await esbuild.context({
      absWorkingDir: root,
      stdin: {
        contents: input,
        resolveDir: root,
        sourcefile: "tapedb-auth-entry.ts",
      },
      outfile: join(root, "tapedb", "auth-page.js"),
      bundle: true,
      write: false,
      format: "esm",
      platform: "browser",
      target: "es2022",
      jsx: "automatic",
      minify: !live,
      define: {
        "process.env.NODE_ENV": JSON.stringify(
          live ? "development" : "production",
        ),
      },
      loader: {
        ".svg": "dataurl",
        ".png": "dataurl",
        ".jpg": "dataurl",
        ".jpeg": "dataurl",
        ".webp": "dataurl",
        ".woff": "dataurl",
        ".woff2": "dataurl",
      },
      plugins: [
        {
          name: "tapedb-auth-page",
          setup(build) {
            build.onEnd(onResult);
          },
        },
      ],
    });
    try {
      await context.rebuild();
      if (live) await context.watch();
      else {
        await context.dispose();
        context = undefined;
      }
    } catch (error) {
      await context?.dispose();
      context = undefined;
      throw error;
    }
  }
  await start();
  let queue = Promise.resolve();
  const watcher = live
    ? watch(root, (_event, file) => {
        if (String(file) !== AUTH_PAGE_FILE) return;
        queue = queue
          .then(start)
          .catch((error) =>
            console.error(
              "Auth page:",
              error instanceof Error ? error.message : String(error),
            ),
          );
      })
    : undefined;
  return {
    async close() {
      closed = true;
      watcher?.close();
      await queue;
      await context?.dispose();
    },
  };
}
